for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++)
        if (a[i] + a[j] == target) return true;

int l = 0, r = n - 1;
while (l < r) {
    int s = a[l] + a[r];
    if (s == target) return true;
    if (s < target) l++;
    else r--;
}
return false;

// remove duplicates from a sorted array
int w = 1;
for (int r = 1; r < n; r++)
    if (a[r] != a[w - 1]) a[w++] = a[r];
// a[0..w-1] are the unique values

int w = 0;
for (int r = 0; r < n; r++)
    if (a[r] != 0) swap(a[w++], a[r]);
